function startMatch(){matchId++;homeScore=0;awayScore=0;matchGoals=0;gameTime=0;paused=false;running=true;shotCooldown=0;ballVelocity.set(0,0,0);player.position.set(0,0,13);player.rotation.y=0;ball.position.set(0,.35,11.8);opponents.forEach((o,i)=>{const p=[[-5,-4],[4,-9],[-8,-15],[8,-18]][i];o.position.set(p[0],0,p[1])});keeper.position.set(0,0,-26);$('score').textContent='0 – 0';$('clock').textContent='00:00';careerScreen.style.display='none';gameRoot.style.display='block';hud.style.display='block';$('joystick').style.display=matchMedia('(pointer:coarse)').matches?'block':'block';modal.style.display='none';if(!scene)buildScene();lastTime=performance.now();showTip();}
function showTip(){const el=$('tip');el.style.opacity='1';clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.style.opacity='0',5200)}
