function setMoveFromKeys(){let x=0,z=0;if(keys.KeyA||keys.ArrowLeft)x--;if(keys.KeyD||keys.ArrowRight)x++;if(keys.KeyW||keys.ArrowUp)z--;if(keys.KeyS||keys.ArrowDown)z++;if(x||z){const l=Math.hypot(x,z);moveInput.x=x/l;moveInput.z=z/l}else if(!joyActive){moveInput.x=0;moveInput.z=0}}
function frame(now){requestAnimationFrame(frame);if(!renderer||!scene)return;const dt=Math.min(.04,(now-lastTime)/1000||.016);lastTime=now;const t=clock3.getElapsedTime();if(running&&!paused)update(dt,t);renderer.render(scene,camera)}
