 // The ball stays at the player's feet while controlled; once kicked it obeys simple arcade physics.
 const distance=ball.position.distanceTo(new THREE.Vector3(player.position.x,.35,player.position.z));if(distance<1.6&&ballVelocity.length()<1.6){ballVelocity.set(0,0,0);ball.position.x=player.position.x+moveInput.x*.35;ball.position.z=player.position.z-.95+moveInput.z*.28}else if(distance<1.85&&ballVelocity.length()<3){ballVelocity.x+=(player.position.x-ball.position.x)*dt*2;ballVelocity.z+=(player.position.z-1-ball.position.z)*dt*2}
 ballVelocity.y-=9.8*dt;ball.position.addScaledVector(ballVelocity,dt);if(ball.position.y<.34){ball.position.y=.34;if(ballVelocity.y< -1.5)ballVelocity.y*=-.28;else ballVelocity.y=0;ballVelocity.x*=Math.pow(.985,dt*60);ballVelocity.z*=Math.pow(.987,dt*60)}ball.rotation.x+=ballVelocity.z*dt*1.6;ball.rotation.z-=ballVelocity.x*dt*1.6;
